// Package bundle builds the per-run bundle.tar.gz that VMSS workers fetch
// from blob storage before starting k6.
//
// Bundle layout inside the tar:
//   runner.js                (k6 entry point → /etc/ddos/runner.js)
//   lib/profile.js
//   lib/transport.js
//   lib/metrics.js
//   scenarios/keepalive-burst.js
//   scenarios/new-conn-flood.js
//   profile.json             (per-run profile → /etc/ddos/profile.json)
//
// The scripts come from the embedded k6/ tree; profile.json is generated by
// the orchestrator (internal/orchestrator/profile package, Phase 5).
package bundle

import (
	"archive/tar"
	"bytes"
	"compress/gzip"
	"encoding/json"
	"fmt"
	"io/fs"
	"path/filepath"
	"strings"
	"time"

	rootassets "github.com/patenvy1234/Http_K6_DDOS"
)

// Build creates a gzip-compressed tar archive containing all k6 scripts from
// the embedded k6/ directory plus the provided profileJSON bytes.
//
// Returns the archive as an in-memory []byte suitable for uploading directly
// to the Azure Blob Storage run container.
func Build(profileJSON []byte) ([]byte, error) {
	var buf bytes.Buffer
	gz, err := gzip.NewWriterLevel(&buf, gzip.BestSpeed)
	if err != nil {
		return nil, fmt.Errorf("bundle: gzip writer: %w", err)
	}
	tw := tar.NewWriter(gz)

	// Walk the embedded k6/ subtree and add every .js file.
	sub, err := fs.Sub(rootassets.K6FS, "k6")
	if err != nil {
		return nil, fmt.Errorf("bundle: sub fs: %w", err)
	}

	modTime := time.Now().UTC()
	if err := fs.WalkDir(sub, ".", func(path string, d fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		if d.IsDir() {
			return nil
		}
		if !strings.HasSuffix(path, ".js") {
			return nil
		}
		content, err := fs.ReadFile(sub, path)
		if err != nil {
			return fmt.Errorf("bundle: read %s: %w", path, err)
		}
		// Normalize CRLF to LF — k6 on Linux doesn't care, but clean is better.
		content = []byte(strings.ReplaceAll(string(content), "\r\n", "\n"))

		hdr := &tar.Header{
			Name:    filepath.ToSlash(path), // always forward-slash in tar
			Size:    int64(len(content)),
			Mode:    0644,
			ModTime: modTime,
			Typeflag: tar.TypeReg,
		}
		if err := tw.WriteHeader(hdr); err != nil {
			return fmt.Errorf("bundle: tar header %s: %w", path, err)
		}
		if _, err := tw.Write(content); err != nil {
			return fmt.Errorf("bundle: tar write %s: %w", path, err)
		}
		return nil
	}); err != nil {
		return nil, err
	}

	// Validate + pretty-print profile.json (catches schema errors early).
	var profileObj any
	if err := json.Unmarshal(profileJSON, &profileObj); err != nil {
		return nil, fmt.Errorf("bundle: invalid profile.json: %w", err)
	}
	prettyProfile, err := json.MarshalIndent(profileObj, "", "  ")
	if err != nil {
		return nil, fmt.Errorf("bundle: re-marshal profile.json: %w", err)
	}

	profHdr := &tar.Header{
		Name:     "profile.json",
		Size:     int64(len(prettyProfile)),
		Mode:     0644,
		ModTime:  modTime,
		Typeflag: tar.TypeReg,
	}
	if err := tw.WriteHeader(profHdr); err != nil {
		return nil, fmt.Errorf("bundle: tar header profile.json: %w", err)
	}
	if _, err := tw.Write(prettyProfile); err != nil {
		return nil, fmt.Errorf("bundle: tar write profile.json: %w", err)
	}

	if err := tw.Close(); err != nil {
		return nil, fmt.Errorf("bundle: tar close: %w", err)
	}
	if err := gz.Close(); err != nil {
		return nil, fmt.Errorf("bundle: gzip close: %w", err)
	}
	return buf.Bytes(), nil
}
